import java.util.*;

public class Hello {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String line = scanner.nextLine().trim();
        assert line.length() >= 1 && line.length() <= 8 : "Invalid input length";
        if (line.charAt(0) == '0') {
            System.out.println(line.length() > 1 ? "0" : "1");
            return;
        }
        int startVal = Integer.parseInt("1" + "0".repeat(line.length() - 1));
        if (startVal == 1) {
            startVal = 0;
        } else if (startVal == 10) {
            startVal = 25;
        }
        int endVal = Integer.parseInt("9".repeat(line.length()));
        int total = 0;
        for (int v = startVal; v <= endVal; v += 25) {
            if (matchesPattern(v, line)) {
                total++;
            }
        }
        System.out.println(total);
    }

    private static boolean matchesPattern(int number, String pattern) {
        String numStr = String.valueOf(number);
        char lastX = '*';
        for (int i = 0; i < pattern.length(); i++) {
            char p = pattern.charAt(i);
            if (p == '_') continue;
            if (p == 'X') {
                if (lastX != '*' && lastX != numStr.charAt(i)) return false;
                lastX = numStr.charAt(i);
            } else if (p != numStr.charAt(i)) {
                return false;
            }
        }
        return true;
    }
}
